26	static const char* state_names[] = {"IDLE", "RECORDING", "UPLOADING", "PLAYING", "ERROR"};
27	static const char* event_names[] = {"BUTTON_PRESS", "RECORD_DONE", "RECORD_TIMEOUT", "UPLOAD_SUCCESS", "UPLOAD_FAIL", "PLAY_DONE", "RETRY", "ERROR"};
