64	    if (g_led2_fd >= 0) {
65	        ioctl(g_led2_fd, GPIOC_WRITE, 1);  /* LED2 灭 */
66	    }
67	
68	    switch (state) {
69	        case STATE_IDLE:
70	            /* 待机: LED1 常亮 */
